class Solution:
    def canMakeSquare(self, grid: list[list[str]]) -> bool:
        for r in range(2):
            for c in range(2):
                b_count = 0
                w_count = 0
                for dr in range(2):
                    for dc in range(2):
                        if grid[r + dr][c + dc] == "B":
                            b_count += 1
                        else:
                            w_count += 1
                if b_count >= 3 or w_count >= 3:
                    return True
        return False
