def findLatestTime(s: str) -> str:
    s = list(s)

    # Handle hours
    if s[0] == "?":
        if s[1] == "?":
            s[0] = "1"
            s[1] = "1"
        elif s[1] in "01":
            s[0] = "1"
        else:
            s[0] = "0"
    else:
        if s[1] == "?":
            if s[0] == "1":
                s[1] = "1"
            else:
                s[1] = "9"

    # Handle minutes
    if s[3] == "?":
        s[3] = "5"
    if s[4] == "?":
        s[4] = "9"

    return "".join(s)
```

