def minOperations(word: str) -> int:
    n = len(word)
    if n == 0:
        return 0  # Not possible per constraints, but handle gracefully

    # Convert characters to integers 0..25
    nums = [ord(ch) - ord('a') for ch in word]

    INF = 10**9
    # dp[i][c] = min operations for prefix up to i with word[i] becoming char c
    dp = [[INF] * 26 for _ in range(n)]

    # Base case: first character
    for c in range(26):
        dp[0][c] = 0 if c == nums[0] else 1

    # Fill DP
    for i in range(1, n):
        for c in range(26):
            cost = 0 if c == nums[i] else 1
            best_prev = INF
            for p in range(26):
                # Not almost-equal: not equal and not adjacent in alphabet
                if p != c and abs(p - c) != 1:
                    best_prev = min(best_prev, dp[i-1][p])
            dp[i][c] = cost + best_prev

    # Answer: min over last character
    return min(dp[n-1])
