def min_changes_partition(s: str, k: int) -> int:
    n = len(s)

    # Precompute changes needed to make s[l:r] into a semi-palindrome
    changes = [[0] * (n + 1) for _ in range(n)]

    for l in range(n):
        for r in range(l + 2, n + 1):  # length >= 2 for semi-palindrome
            length = r - l
            best = length  # maximum changes is length
            for d in range(1, length):
                if length % d == 0:
                    # For each residue class modulo d, we need it to be palindrome
                    total_changes = 0
                    for mod in range(d):
                        chars = []
                        for pos in range(l + mod, r, d):
                            chars.append(s[pos])
                        # Minimum changes to make this sequence palindrome
                        m = len(chars)
                        pal_changes = 0
                        for i in range(m // 2):
                            if chars[i] != chars[m - 1 - i]:
                                pal_changes += 1
                        total_changes += pal_changes
                    best = min(best, total_changes)
            changes[l][r] = best

    # dp[i][j] = min changes to partition s[0:i] into j semi-palindromes
    INF = 10**9
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            for cut in range(0, i):
                if i - cut >= 2:  # Substring length must be at least 2
                    dp[i][j] = min(dp[i][j], dp[cut][j - 1] + changes[cut][i])

    return dp[n][k]

