def longest_common_suffix(wordsContainer, wordsQuery):
    class TrieNode:
        __slots__ = ('children', 'best_len', 'best_idx')
        def __init__(self):
            self.children = {}
            self.best_len = float('inf')
            self.best_idx = -1

    root = TrieNode()
    # Insert all container words into the trie (reversed)
    for idx, word in enumerate(wordsContainer):
        length = len(word)
        # Update root
        if length < root.best_len or (length == root.best_len and idx < root.best_idx):
            root.best_len = length
            root.best_idx = idx
        node = root
        # Traverse the reversed word, updating each node
        for ch in reversed(word):
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            if length < node.best_len or (length == node.best_len and idx < node.best_idx):
                node.best_len = length
                node.best_idx = idx

    # Answer each query
    result = []
    for query in wordsQuery:
        node = root
        for ch in reversed(query):
            if ch in node.children:
                node = node.children[ch]
            else:
                break
        result.append(node.best_idx)
    return result
