def find_prime_pairs(n):
    """
    Return all prime pairs (x, y) with 1 <= x <= y <= n, x + y == n,
    and both x and y prime. The pairs are sorted by x.
    """
    # No pairs possible for n < 4 because smallest prime sum is 2+2=4
    if n < 4:
        return []

    # Sieve of Eratosthenes to find all primes up to n
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    pairs = []
    # Only need to check x up to n//2 to ensure x <= y
    for x in range(2, n // 2 + 1):
        if is_prime[x] and is_prime[n - x]:
            pairs.append([x, n - x])
    return pairs
