def min_lexicographic_string(a: str, b: str, c: str) -> str:
    def merge(s1: str, s2: str) -> str:
        """Return shortest string that has s1 and s2 as substrings, with s1 before s2 if possible, else try overlapping."""
        if s2 in s1:
            return s1
        for i in range(min(len(s1), len(s2)), 0, -1):
            if s1[-i:] == s2[:i]:
                return s1 + s2[i:]
        return s1 + s2

    def combine_three(x: str, y: str, z: str) -> str:
        return merge(merge(x, y), z)

    import itertools
    best = None
    for perm in itertools.permutations([a, b, c]):
        candidate = combine_three(*perm)
        if best is None or len(candidate) < len(best) or (len(candidate) == len(best) and candidate < best):
            best = candidate
    return best
