def maxLength(x: int, y: int, z: int) -> int:
    # dp[i][j][k][last] = max number of strings used to reach state with
    # i AA, j BB, k AB used, and the last string is of type 'last'.
    # last: 0 = AA, 1 = BB, 2 = AB, 3 = start (no previous string)
    dp = [[[[ -1 for _ in range(4)] for _ in range(z+1)] for _ in range(y+1)] for _ in range(x+1)]
    dp[0][0][0][3] = 0  # start

    for i in range(x+1):
        for j in range(y+1):
            for k in range(z+1):
                for last in range(4):
                    cur = dp[i][j][k][last]
                    if cur == -1:
                        continue
                    # try to add an "AA"
                    if i < x:
                        if last == 3 or last == 1 or last == 2:  # start, BB, AB
                            if dp[i+1][j][k][0] < cur + 1:
                                dp[i+1][j][k][0] = cur + 1
                    # try to add a "BB"
                    if j < y:
                        if last == 3 or last == 0:  # start, AA
                            if dp[i][j+1][k][1] < cur + 1:
                                dp[i][j+1][k][1] = cur + 1
                    # try to add an "AB"
                    if k < z:
                        if last == 3 or last == 1 or last == 2:  # start, BB, AB
                            if dp[i][j][k+1][2] < cur + 1:
                                dp[i][j][k+1][2] = cur + 1

    ans = 0
    for i in range(x+1):
        for j in range(y+1):
            for k in range(z+1):
                for last in range(4):
                    if dp[i][j][k][last] != -1:
                        ans = max(ans, 2 * (i + j + k))
    return ans
