        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)

    W = [0] * N
    for i in range(N):
        W[i] = int(next(it))

    A = [0] * N
    for i in range(N):
        A[i] = int(next(it))

    # vertices in increasing order of weight
    order = sorted(range(N), key=lambda i: W[i])

    f = [0] * N        # f[i] = max operations from a single piece at i

    for i in order:
        cap = W[i] - 1          # sum of neighbour weights must be < W[i]
        if cap < 0:
            cap = 0

        # collect eligible neighbours: W[nb] < W[i]
        items = []
        for nb in adj[i]:
            if W[nb] < W[i]:
                items.append((W[nb], f[nb]))

        if not items:
            best = 0
        else:
            # 0/1 knapsack: capacity = cap, maximize sum of f[nb]
            dp = [-1] * (cap + 1)
            dp[0] = 0
            for w, v in items:
                if w > cap:
                    continue
                for c in range(cap, w - 1, -1):
                    if dp[c - w] != -1:
                        cand = dp[c - w] + v
                        if cand > dp[c]:
                            dp[c] = cand
            best = max(dp)

        f[i] = 1 + best

    ans = 0
    for i in range(N):
        ans += A[i] * f[i]
    print(ans)


