    # initial scan: intervals exactly equal to T
    for i in range(N - M + 1):
        ok = True
        for j in range(M):
            if cur[i + j] != T[j]:
                ok = False
                break
        if ok:
            q.append(i)
            in_queue[i] = True

    while q:
        i = q.popleft()
        # The interval [i, i+M-1] must still be stampable (it always is, but check for safety)
        for p in range(i, i + M):
            if cur[p] != '#':
                cur[p] = '#'
                # check intervals that become stampable because this position turned to '#'
                left = max(0, p - M + 1)
