def punishmentNumber(n: int) -> int:
    def can_partition(s: str, target: int) -> bool:
        # Use recursion to try all ways to split s into substrings
        # whose integer values sum to target.
        def backtrack(start: int, current_sum: int) -> bool:
            if start == len(s):
                return current_sum == target
            # Try all possible substrings starting at 'start'
            for end in range(start + 1, len(s) + 1):
                part = int(s[start:end])
                if current_sum + part <= target:
                    if backtrack(end, current_sum + part):
                        return True
            return False
        return backtrack(0, 0)

    total = 0
    for i in range(1, n + 1):
        square_str = str(i * i)
        if can_partition(square_str, i):
            total += i * i
    return total
