import math

def minimum_cost_to_convert_string(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    # Initialize distance matrix for 26 lowercase letters
    INF = 10**15
    dist = [[INF] * 26 for _ in range(26)]

    # Set self-distance to 0
    for i in range(26):
        dist[i][i] = 0

    # Fill with direct conversion costs (keep minimum if multiple edges exist)
    for o, c, w in zip(original, changed, cost):
        u = ord(o) - ord('a')
        v = ord(c) - ord('a')
        dist[u][v] = min(dist[u][v], w)

    # Floyd-Warshall to find minimum cost between any two characters
    for k in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][k] < INF and dist[k][j] < INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    for s_char, t_char in zip(source, target):
        u = ord(s_char) - ord('a')
        v = ord(t_char) - ord('a')
        if dist[u][v] >= INF:
            return -1
        total_cost += dist[u][v]

    return total_cost
