    segments = []
    start = 0
    for i in range(n - 1):
        if abs(ord(word[i]) - ord(word[i + 1])) > 2:
            segments.append(word[start:i + 1])
            start = i + 1
    segments.append(word[start:])   # last segment

    ans = 0
    for seg in segments:
        seg_len = len(seg)
        if seg_len < k:
            continue
        max_m = min(26, seg_len // k)   # number of distinct characters possible
        for m in range(1, max_m + 1):
            L = m * k                     # window length
            freq = [0] * 26
            invalid = 0                   # count of characters with freq not 0 and not k

            # ---- initial window ----
            for ch in seg[:L]:
                idx = ord(ch) - 97
                prev = freq[idx]
                freq[idx] += 1
                new = freq[idx]
                if prev == 0:
                    if new != k:
                        invalid += 1
                elif prev == k:
                    invalid += 1           # now > k
                elif new == k:
                    invalid -= 1           # was invalid, now exactly k
            if invalid == 0:
                ans += 1

            # ---- slide the window ----
            for i in range(L, seg_len):
                # character to the right (new window)
                ch_add = seg[i]
                idx_add = ord(ch_add) - 97
                prev = freq[idx_add]
                freq[idx_add] += 1
                new = freq[idx_add]
                if prev == 0:
                    if new != k:
                        invalid += 1
                elif prev == k:
                    invalid += 1
                elif new == k:
                    invalid -= 1

                # character to the left (leaving window)
                ch_rem = seg[i - L]
                idx_rem = ord(ch_rem) - 97
                prev = freq[idx_rem]
                freq[idx_rem] -= 1
                new = freq[idx_rem]
                if prev == k:
                    if new != 0:
                        invalid += 1          # now not k and not 0
                elif prev > k:
                    if new == k:
                        invalid -= 1
                    # if new == 0 impossible because prev>k>=1
                else:  # 0 < prev < k  (invalid)
                    if new == 0:
                        invalid -= 1

                if invalid == 0:
                    ans += 1
    return ans
