def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    N = next(it)

    # 1-indexed adjacency lists
    prereqs = [None] * (N + 1)          # prerequisites of each book
    dependents = [[] for _ in range(N + 1)]  # books that depend on a given book

    for i in range(1, N + 1):
        c = next(it)
        if c > 0:
            lst = [next(it) for _ in range(c)]
        else:
            lst = []
        prereqs[i] = lst
        for p in lst:
            dependents[p].append(i)

    # 1. find all books required to read book 1 (transitive closure of its prerequisites)
    needed = [False] * (N + 1)
    q = deque([1])
    needed[1] = True
    while q:
        u = q.popleft()
        for p in prereqs[u]:
            if not needed[p]:
                needed[p] = True
                q.append(p)

    # 2. topological order of the needed subgraph (including book 1)
    indeg = [0] * (N + 1)
    for i in range(1, N + 1):
        if needed[i]:
            indeg[i] = len(prereqs[i])

    q = deque()
    for i in range(1, N + 1):
        if needed[i] and indeg[i] == 0:
            q.append(i)

    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in dependents[u]:
            if needed[v]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)

    # 3. output everything except book 1
    out = [str(x) for x in topo if x != 1]
    sys.stdout.write(' '.join(out))

if __name__ == "__main__":
