import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    H = int(next(it))
    W = int(next(it))

    tiles = []
    total_area = 0
    for _ in range(N):
        a = int(next(it))
        b = int(next(it))
        tiles.append((a, b))
        total_area += a * b

    # Necesssary condition: total area of all tiles must be at least H*W
    if total_area < H * W:
        print("No")
        return

    # Initialize the grid (False = empty)
    grid = [[False] * W for _ in range(H)]
    used = [False] * N

    def backtrack(remaining: int, unused_area: int) -> bool:
        # All cells covered
        if remaining == 0:
            return True
        # Not enough area left in unused tiles to fill the rest
        if remaining > unused_area:
            return False

        # Find the first empty cell (top-leftmost)
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    # Try every unused tile
                    for idx, (a, b) in enumerate(tiles):
                        if used[idx]:
                            continue
                        area = a * b
                        if area > remaining:
                            continue

                        # Orientations to try
                        if a == b:
                            orientations = [(a, b)]
                        else:
                            orientations = [(a, b), (b, a)]

                        for da, db in orientations:
                            if r + da > H or c + db > W:
                                continue
                            # Check all cells of the rectangle are empty
                            ok = True
                            for i in range(r, r + da):
                                for j in range(c, c + db):
                                    if grid[i][j]:
                                        ok = False
                                        break
                                if not ok:
                                    break
                            if not ok:
                                continue

                            # Place the tile
                            for i in range(r, r + da):
                                for j in range(c, c + db):
                                    grid[i][j] = True
                            used[idx] = True

                            if backtrack(remaining - area, unused_area - area):
                                return True

                            # Undo placement
                            used[idx] = False
                            for i in range(r, r + da):
                                for j in range(c, c + db):
                                    grid[i][j] = False

                    # No tile can cover this cell -> dead end
                    return False
        # Should never reach here (if remaining>0 there is an empty cell)
        return False

    if backtrack(H * W, total_area):
        print("Yes")
    else:
        print("No")


if __name__ == "__main__":
    solve()
