def min_beautiful_partitions(s: str) -> int:
    # Precompute all binary strings for powers of 5 up to maximum possible length
    powers_of_5 = set()
    num = 1
    while True:
        bin_str = bin(num)[2:]  # remove '0b' prefix
        if len(bin_str) > len(s):
            break
        powers_of_5.add(bin_str)
        num *= 5

    n = len(s)
    # dp[i] = minimum beautiful partitions for s[i:]
    INF = 10**9
    dp = [INF] * (n + 1)
    dp[n] = 0  # empty suffix needs 0 partitions

    for i in range(n - 1, -1, -1):
        if s[i] == '0':
            # leading zero not allowed
            continue
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            if substring in powers_of_5:
                if dp[j] != INF:
                    dp[i] = min(dp[i], 1 + dp[j])

    return dp[0] if dp[0] != INF else -1

