from functools import lru_cache

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    # suffix length and value
    L = len(s)
    suffix = int(s)
    factor = 10 ** L

    # no number can be ≤ finish if suffix itself is larger
    if suffix > finish:
        return 0

    # range of prefixes p such that p * factor + suffix ∈ [start, finish]
    p_min = (start - suffix + factor - 1) // factor
    if p_min < 0:
        p_min = 0
    p_max = (finish - suffix) // factor

    if p_min > p_max:
        return 0

    # digit DP: count numbers in [0, x] with every digit ≤ limit
    def count_upto(x: int) -> int:
        if x < 0:
            return 0
        digits = list(map(int, str(x)))
        n = len(digits)

        @lru_cache(None)
        def dp(pos: int, tight: bool, started: bool) -> int:
            if pos == n:
                return 1  # the number formed (including zero) is valid
            limit_digit = digits[pos] if tight else 9
            total = 0
            # allowed digits are 0 .. min(limit_digit, limit)
            for d in range(0, min(limit_digit, limit) + 1):
                if not started:
                    if d == 0:
                        # still not started (leading zero)
                        total += dp(pos + 1, tight and (d == limit_digit), False)
                    else:
                        # start the number with this digit
                        total += dp(pos + 1, tight and (d == limit_digit), True)
                else:
                    # already started, any digit is allowed
                    total += dp(pos + 1, tight and (d == limit_digit), True)
            return total

        return dp(0, True, False)

    # count prefixes in [p_min, p_max]
    return count_upto(p_max) - count_upto(p_min - 1)
