    it = iter(data)
    N = int(next(it))
    Q = int(next(it))

    # boxes: list of dicts, 1-indexed
    boxes = [{} for _ in range(N + 1)]
    for i in range(1, N + 1):
        c = int(next(it))
        boxes[i][c] = 1

    out_lines = []
    for _ in range(Q):
        a = int(next(it))
        b = int(next(it))

        # If source is empty, answer is size of target
        if not boxes[a]:
            out_lines.append(str(len(boxes[b])))
            continue

        # If target is empty, just move the whole dict and clear source
        if not boxes[b]:
            boxes[b] = boxes[a]
            boxes[a] = {}
            out_lines.append(str(len(boxes[b])))
            continue

        # Both non‑empty: merge smaller into larger, always keep union in box b
        if len(boxes[a]) > len(boxes[b]):
            # merge b into a, then assign a's dict to b
            for col, cnt in boxes[b].items():
                boxes[a][col] = boxes[a].get(col, 0) + cnt
            boxes[b] = boxes[a]
            boxes[a] = {}
        else:
            # merge a into b
            for col, cnt in boxes[a].items():
                boxes[b][col] = boxes[b].get(col, 0) + cnt
            boxes[a] = {}

        out_lines.append(str(len(boxes[b])))

    sys.stdout.write("\n".join(out_lines))

