def mostFrequentID(nums, freq):
    import heapq
    id_freq = {}
    freq_count = {}
    heap = []
    n = len(nums)
    ans = [0] * n

    for i in range(n):
        id_val = nums[i]
        delta = freq[i]
        old = id_freq.get(id_val, 0)
        new = old + delta

        if old > 0:
            freq_count[old] -= 1
            # optional cleanup of zero count keys is not necessary

        if new > 0:
            id_freq[id_val] = new
            freq_count[new] = freq_count.get(new, 0) + 1
            heapq.heappush(heap, -new)
        else:
            # new == 0, remove the id from tracking
            if id_val in id_freq:
                del id_freq[id_val]

        # remove stale entries from the heap
        while heap and freq_count.get(-heap[0], 0) == 0:
            heapq.heappop(heap)

        ans[i] = -heap[0] if heap else 0

    return ans
