from typing import List

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n <= 1:
        return True

    max_val = max(nums)

    # sieve for smallest prime factor (SPF)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Disjoint Set Union (Union-Find)
    parent = list(range(n + max_val + 1))
    rank = [0] * (n + max_val + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    # Connect each index to its prime factors
    for i, num in enumerate(nums):
        if num == 1:
            continue
        # extract distinct prime factors
        factors = set()
        x = num
        while x > 1:
            p = spf[x]
            factors.add(p)
            while x % p == 0:
                x //= p
        for p in factors:
            union(i, n + p)

    # Check if all indices are in the same component
    root0 = find(0)
    for i in range(1, n):
        if find(i) != root0:
            return False
    return True
