from typing import List

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x: int, y: int) -> None:
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1

def lexicographicallySmallestArray(nums: List[int], limit: int) -> List[int]:
    n = len(nums)
    dsu = DSU(n)
    # Pair each value with its original index and sort by value
    indexed = sorted((val, idx) for idx, val in enumerate(nums))
    # Union indices of consecutive values that differ by <= limit
    for i in range(n - 1):
        if indexed[i + 1][0] - indexed[i][0] <= limit:
            dsu.union(indexed[i][1], indexed[i + 1][1])
    # Group indices by component root
    comp = {}
    for idx in range(n):
        root = dsu.find(idx)
        comp.setdefault(root, []).append(idx)
    # Build result array
    res = [0] * n
    for indices in comp.values():
        # Sorted indices in increasing order (they come from DSU, but we sort)
        idxs = sorted(indices)
        # Collect values at those indices and sort them
        vals = sorted(nums[i] for i in idxs)
        # Assign smallest value to smallest index, etc.
        for i, v in zip(idxs, vals):
            res[i] = v
    return res
```

