        new_dp = [0] * (n + 1)
        if ch == '(':
            # only '('
            for b in range(n):
                if dp[b]:
                    new_dp[b + 1] = (new_dp[b + 1] + dp[b]) % MOD
        elif ch == ')':
            # only ')', need b>0
            for b in range(1, n + 1):
                if dp[b]:
                    new_dp[b - 1] = (new_dp[b - 1] + dp[b]) % MOD
        else:  # '?'
