def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)
    # Precompute divisibility: can[i][j] = True if nums[i] divides nums[j] or vice versa
    can = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                can[i][j] = True
    # dp[mask][last] = number of permutations ending with last, using indices in mask
    dp = [[0] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = 1
    for mask in range(1 << n):
        for last in range(n):
            if not (mask >> last) & 1:
                continue
            cur = dp[mask][last]
            if cur == 0:
                continue
            for nxt in range(n):
                if (mask >> nxt) & 1:
                    continue
                if can[last][nxt]:
                    dp[mask | (1 << nxt)][nxt] = (dp[mask | (1 << nxt)][nxt] + cur) % MOD
    full_mask = (1 << n) - 1
    ans = sum(dp[full_mask][i] for i in range(n)) % MOD
    return ans
```

