import sys
import itertools

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    R = data[1].strip()
    C = data[2].strip()

    # per row, we store the list of (col, letter) placements
    row_placements = [[] for _ in range(N)]

    # column state
    col_used = [set() for _ in range(N)]      # letters already placed in column
    col_top = [None] * N                      # letter of the topmost placed cell
    col_top_row = [-1] * N                    # row of that topmost cell

    def can_place(row: int, col: int, letter: str) -> bool:
        """Check if letter can be placed at (row, col) without violating
        the column constraints."""
        if letter in col_used[col]:
            return False
        if col_top[col] is None:
            # this will become the topmost cell of the column
            if letter != C[col]:
                return False
        return True

    def place(row: int, col: int, letter: str) -> None:
        """Place letter at (row, col) and update column state."""
        col_used[col].add(letter)
        if col_top[col] is None:
            col_top[col] = letter
            col_top_row[col] = row
        row_placements[row].append((col, letter))

    def undo(row: int, col: int, letter: str) -> None:
        """Remove the letter from (row, col) and restore column state."""
        col_used[col].remove(letter)
        if col_top_row[col] == row:
            col_top[col] = None
            col_top_row[col] = -1
        row_placements[row].pop()

    def backtrack(row: int) -> bool:
        """Try to fill rows from `row` onward. Returns True on success."""
        if row == N:
            # all rows placed → check that every column contains all three letters
            for j in range(N):
                if len(col_used[j]) != 3:
                    return False
            return True

        target = R[row]
        # choose 3 columns for this row
        for cols in itertools.combinations(range(N), 3):
            left_col = min(cols)
            # the leftmost column must get the row's target letter
            if not can_place(row, left_col, target):
                continue

            other_cols = [c for c in cols if c != left_col]
            other_letters = [l for l in ('A', 'B', 'C') if l != target]

            # assign the remaining two letters in all possible orders
            for perm in itertools.permutations(other_letters):
                # check that the other placements are valid
                valid = True
                for col, let in zip(other_cols, perm):
                    if not can_place(row, col, let):
                        valid = False
                        break
                if not valid:
                    continue

                # apply placements
                place(row, left_col, target)
                for col, let in zip(other_cols, perm):
                    place(row, col, let)

                # recurse
                if backtrack(row + 1):
                    return True

                # undo placements
                undo(row, left_col, target)
                for col, let in zip(other_cols, perm):
                    undo(row, col, let)

        return False

    if backtrack(0):
        grid = [['.'] * N for _ in range(N)]
        for i in range(N):
            for col, letter in row_placements[i]:
                grid[i][col] = letter
        print("Yes")
        for line in grid:
            print(''.join(line))
    else:
        print("No")

if __name__ == "__main__":
    solve()
```

