    max_time = 3 * M
    INF = 10**9
    ans = INF

    for d in range(10):
        digit = str(d)
        # Build lists of allowed times for each reel
        L1 = [t for t in range(max_time + 1) if S1[t % M] == digit]
        L2 = [t for t in range(max_time + 1) if S2[t % M] == digit]
        L3 = [t for t in range(max_time + 1) if S3[t % M] == digit]

        # If any reel has no occurrence, skip this digit
        if not L1 or not L2 or not L3:
            continue

        # Iterate over all triples of distinct times
        for t1 in L1:
            for t2 in L2:
                if t2 == t1:
                    continue
                for t3 in L3:
                    if t3 == t1 or t3 == t2:
                        continue
                    cur = max(t1, t2, t3)
                    if cur < ans:
                        ans = cur
                        # Early exit: we can't get smaller than 0
                        if ans == 0:
                            print(0)
                            return

    if ans == INF:
        print(-1)
    else:
        print(ans)

