from functools import lru_cache
from typing import List

def max_jumps(nums: List[int], target: int) -> int:
    n = len(nums)

    @lru_cache(None)
    def dp(i: int) -> int:
        if i == n - 1:
            return 0
        max_jumps_count = -1
        for j in range(i + 1, n):
            if abs(nums[j] - nums[i]) <= target:
                sub_result = dp(j)
                if sub_result != -1:
                    max_jumps_count = max(max_jumps_count, 1 + sub_result)
        return max_jumps_count

    result = dp(0)
    return result if result != -1 else -1
