def min_operations(s1: str, s2: str, s3: str) -> int:
    # Compute longest common prefix length
    L = 0
    min_len = min(len(s1), len(s2), len(s3))
    while L < min_len and s1[L] == s2[L] == s3[L]:
        L += 1

    if L == 0:
        return -1

    # Minimum number of deletions = sum of lengths - 3 * L
    return (len(s1) - L) + (len(s2) - L) + (len(s3) - L)
