def max_good_subarray_sum(nums, k):
    n = len(nums)
    # prefix sums: prefix[i] = sum of nums[0..i-1]
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    # map from value to maximum prefix sum (prefix[j+1]) for indices j already processed
    val_to_max_prefix = {}
    ans = float('-inf')

    # process from right to left, treating each index as potential start
    for i in range(n - 1, -1, -1):
        val = nums[i]
        # consider the two possible endings
        for target in (val + k, val - k):
            if target in val_to_max_prefix:
                max_prefix = val_to_max_prefix[target]
                # sum of subarray from i to j = prefix[j+1] - prefix[i]
                candidate = max_prefix - prefix[i]
                if candidate > ans:
                    ans = candidate

        # update map with current index as a possible end for future starts
        curr_prefix = prefix[i + 1]
        if val in val_to_max_prefix:
            val_to_max_prefix[val] = max(val_to_max_prefix[val], curr_prefix)
        else:
            val_to_max_prefix[val] = curr_prefix

    return 0 if ans == float('-inf') else ans
```

