import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])
    S = input_data[2]

    # We need to find the minimum number of logo T-shirts (let this be X).
    # Since the constraint is small (N <= 1000), we can simulate for each 
    # potential number of logo T-shirts X, or use a binary search.
    # However, since X can range from 0 to N, we can just check if X is sufficient.

    def can_manage(logo_needed):
        plain_available = M
        logo_available = logo_needed

        for char in S:
            if char == '0':
                # Wash all
                plain_available = M
                logo_available = logo_needed
            elif char == '1':
                # Prefers plain if available
                if plain_available > 0:
                    plain_available -= 1
                elif logo_available > 0:
                    logo_available -= 1
                else:
                    return False
            elif char == '2':
                # Must be logo
                if logo_available > 0:
                    logo_available -= 1
                else:
                    return False
        return True

    # Binary search for the minimum logo_needed
    low = 0
    high = N
    ans = N

    while low <= high:
        mid = (low + high) // 2
        if can_manage(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    print(ans)

if __name__ == '__main__':
    solve()
```

