def countKeyChanges(s):
    if not s:
        return 0

    changes = 0
    prev_char = s[0].lower()  # Convert to lowercase for case-insensitive comparison

    for i in range(1, len(s)):
        curr_char = s[i].lower()  # Convert to lowercase for case-insensitive comparison
