def countSubMultisets(nums, l, r):
    MOD = 10**9 + 7
    # Count frequency of each number
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    # dp[i] represents the number of ways to achieve sum i
    dp = [0] * (max(r, sum(nums)) + 1)
    dp[0] = 1  # Empty subset has sum 0

    # Process each unique number
    for num, count in freq.items():
        new_dp = dp[:]
        # For each possible sum
        for i in range(len(dp)):
            if dp[i] == 0:
                continue
            # Add 1, 2, ..., count occurrences of num
            for k in range(1, count + 1):
                new_sum = i + k * num
                if new_sum < len(dp):
                    new_dp[new_sum] = (new_dp[new_sum] + dp[i]) % MOD
        dp = new_dp

    # Sum up all valid sums in range [l, r]
    result = 0
    for i in range(l, r + 1):
        if i < len(dp):
            result = (result + dp[i]) % MOD

    return result
