                # d is a prime factor
                if d in prime_to_index:
                    # Connect current index with the previous index having this prime factor
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                # Remove all occurrences of d
                while temp % d == 0:
                    temp //= d
            d += 1
        # If temp is still > 1, then it's a prime factor itself
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

