def get_smallest_string(s: str, k: int) -> str:
    def char_distance(c1: str, c2: str) -> int:
        diff = abs(ord(c1) - ord(c2))
        return min(diff, 26 - diff)

    s_list = list(s)
    n = len(s_list)

    for i in range(n):
        # Try changing s[i] to the lexicographically smallest possible character
        # while keeping the total distance <= k
        for target in range(ord('a'), ord('z') + 1):
            target_char = chr(target)
            dist_needed = char_distance(s_list[i], target_char)

            if dist_needed <= k:
                s_list[i] = target_char
                k -= dist_needed
                break

    return ''.join(s_list)
