def minOperations(s1: str, s2: str, s3: str) -> int:
    # If the first characters don't match, it's impossible to make them equal
    if s1[0] != s2[0] or s1[0] != s3[0] or s2[0] != s3[0]:
        return -1

    # Find the length of the longest common prefix
    min_len = min(len(s1), len(s2), len(s3))
    match_len = 0

    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            match_len += 1
        else:
            break

    # Total operations = (len(s1) - match_len) + (len(s2) - match_len) + (len(s3) - match_len)
    return (len(s1) + len(s2) + len(s3)) - (3 * match_len)
```

